import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "caret-up",
  "category": "Navigation",
  "viewBox": "0 0 256 256",
  "mode": "fill",
  "strokeWidth": 0,
  "motion": "slideUp",
  "parts": [
    {
      "tag": "path",
      "attrs": {
        "d": "M213.66,165.66a8,8,0,0,1-11.32,0L128,91.31,53.66,165.66a8,8,0,0,1-11.32-11.32l80-80a8,8,0,0,1,11.32,0l80,80A8,8,0,0,1,213.66,165.66Z"
      }
    }
  ],
  "accents": []
};

export const meta = {
  "slug": "phosphor-caret-up",
  "family": "phosphor",
  "name": "caret-up",
  "category": "Navigation",
  "motion": "slideUp",
  "component": "createPhosphorCaretUpIcon"
};

export function createPhosphorCaretUpIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
